#!/usr/bin/env Rscript
source(file.path(dirname(normalizePath(sub("^--file=", "", commandArgs(FALSE)[grep("^--file=", commandArgs(FALSE))]))), "dv_shared.R"))
dv_require(c("limma","statmod","digest"));hash<-dv_assert_candidate_hash();stage<-"D06_environment_interaction";outdir<-dv_stage_dir(stage)
meta<-dv_assignment("Discovery");ef<-file.path(dv_stage_dir("D01_discovery_eligibility"),"D01_discovery_eligible_expression.csv.gz");expr<-dv_read_expression(ef,meta$UniqueSampleID,TRUE);lock<-dv_read_csv(file.path(dv_stage_dir("D03_candidate_lock"),"D03_locked_candidates.csv"),"PG.ProteinGroups");expr<-expr[match(lock$PG.ProteinGroups,rownames(expr)),,drop=FALSE]
d<-dv_design(meta,TRUE); req<-make.names(as.vector(outer(DV_DOSE,DV_ENV,paste,sep="__")));if(!all(req%in%colnames(d)))dv_stop("NON_ESTIMABLE: missing Environment x Dose cell")
ct<-limma::makeContrasts(Interaction_Long_vs_Short=(high__Humid.hot-low__Humid.hot)-(high__High.pressure.high.altitude-low__High.pressure.high.altitude),Interaction_Short_vs_Control=(low__Humid.hot-control__Humid.hot)-(low__High.pressure.high.altitude-control__High.pressure.high.altitude),Interaction_Long_vs_Control=(high__Humid.hot-control__Humid.hot)-(high__High.pressure.high.altitude-control__High.pressure.high.altitude),levels=d)
r<-dv_fit(expr,d,ct,family_n=nrow(expr));r$Secondary_BH_FDR<-ave(r$P_value,r$Contrast,FUN=function(p)p.adjust(p,"BH",n=nrow(expr)))
paths<-file.path(outdir,c("D06_candidate_interaction_results.csv","D06_design_matrix.csv","D06_manifest.csv"));dv_no_overwrite(paths);dv_write(dv_add_annotation(r),paths[1]);dv_write(cbind(UniqueSampleID=meta$UniqueSampleID,d),paths[2]);dv_write(dv_manifest(stage,c(ef,file.path(dv_stage_dir("D03_candidate_lock"),"D03_locked_candidates.csv")),paths[1:2],list(candidate_hash=hash,primary_interaction="(Long-Short)_Humid-hot - (Long-Short)_High-pressure/high-altitude",multiplicity="BH separately per interaction contrast; investigator approval required before execution")),paths[3])
